using System;using System.Collections.Generic;using Ashfall.Core;using Ashfall.Integration.Playable.HandsWeapons;
class HullCases
{
 static int checks;static void Need(bool x,string why){checks++;if(!x)throw new Exception(why);}static Float3 Sub(Float3 a,Float3 b){return new Float3(a.X-b.X,a.Y-b.Y,a.Z-b.Z);}static Float3 Cross(Float3 a,Float3 b){return new Float3(a.Y*b.Z-a.Z*b.Y,a.Z*b.X-a.X*b.Z,a.X*b.Y-a.Y*b.X);}static double Dot(Float3 a,Float3 b){return(double)a.X*b.X+(double)a.Y*b.Y+(double)a.Z*b.Z;}
 static void Check(Float3[] cloud){Float3[] v;int[] t;Need(R24KnifeHull.TryBuild(cloud,out v,out t),"actual source cloud produces closed volume");var edges=new Dictionary<long,int>();double volume=0;for(int i=0;i<t.Length;i+=3){int a=t[i],b=t[i+1],c=t[i+2];var normal=Cross(Sub(v[b],v[a]),Sub(v[c],v[a]));Need(Dot(normal,normal)>1e-17,"nondegenerate actual hull faces");foreach(var p in cloud)Need(Dot(normal,Sub(p,v[a]))<=.000002*Math.Sqrt(Dot(normal,normal)),"all exact source cloud vertices inside/on cooked hull envelope");volume+=Dot(v[a],Cross(v[b],v[c]))/6;foreach(var e in new[]{new[]{a,b},new[]{b,c},new[]{c,a}}){long key=((long)Math.Min(e[0],e[1])<<32)|(uint)Math.Max(e[0],e[1]);int count;edges.TryGetValue(key,out count);edges[key]=count+1;}}Need(volume>0,"outward positive volume, no open triangle fan");foreach(var count in edges.Values)Need(count==2,"closed manifold everyedge exactly two adjacent faces");for(int axis=0;axis<3;axis++)foreach(int sign in new[]{-1,1}){double a=double.NegativeInfinity,b=a;foreach(var p in cloud)a=Math.Max(a,sign*(axis==0?p.X:axis==1?p.Y:p.Z));foreach(var p in v)b=Math.Max(b,sign*(axis==0?p.X:axis==1?p.Y:p.Z));Need(Math.Abs(a-b)<.000002,"same source cloud support extent, no added collision box");}}
 static void Main(){foreach(float length in new[]{.221f,1.0f})foreach(float angle in new[]{0f,.03f,.1f,.35f,1.3f})foreach(float travel in new[]{0f,.025f,.2f}){var a=new Float3();var b=new Float3(0,length,0);var c=new Float3(travel,0,0);var d=new Float3(travel+length*(float)Math.Sin(angle),length*(float)Math.Cos(angle),0);Check(R24KnifeMath.HullPoints(a,b,c,d,.001f));}Float3[] v;int[] t;Need(!R24KnifeHull.TryBuild(new[]{new Float3(),new Float3(1,0,0),new Float3(2,0,0),new Float3(3,0,0)},out v,out t),"flat invalid source rejected without synthetic shape");Console.WriteLine("PASS "+checks+" closed actual source convex hull geometric invariants over30 blade clouds; no Unity cooking executed");}
}
